SELECT COALESCE(SUM(total_seconds), 0)
FROM weekly_study_time
WHERE student_id = #{studentId}
  AND course_id IS NULL
  AND week_start_date = #{weekStartDate}

SELECT COALESCE(total_seconds, 0)
FROM weekly_study_time
WHERE student_id = #{studentId}
  AND course_id = #{courseId}
  AND week_start_date = #{weekStartDate}
LIMIT 1
